from solution import is_power_of_two
import time

def test_1():
    x = 2**300000
    t = time.perf_counter()
    r1, r2 = is_power_of_two(x), is_power_of_two(x + 1)
    assert time.perf_counter() - t < 0.01
    assert r1 is True and r2 is False

def test_2():
    assert is_power_of_two(1) == True

def test_3():
    assert is_power_of_two(6) == False

def test_4():
    assert is_power_of_two(0) == False


if __name__ == "__main__":
